var EXPLICIT_SELF_MODIFICATION_PATTERNS = [
  /\b(?:update|change|modify|adjust|tweak|revise|refresh|set)\s+(?:(?:your|ur|its)\s+)?(?:personality|character|tone|voice|style|behavior|behaviour|response(?:s| style)?|how\s+you\s+respond|way\s+you\s+respond)\b/i,
  /\b(?:update|change|modify|adjust|tweak|revise|refresh|set)\s+(?:the\s+|this\s+)?(?:agent|assistant|bot)(?:'s)?\s+(?:personality|character|tone|voice|style|behavior|behaviour|response(?:\s+style)?)\b/i,
  /\b(?:change|update|modify|adjust|set)\s+(?:your\s+)?response\s+style\b/i,
  /\b(?:change|update|modify|adjust|set)\s+how\s+you\s+(?:respond|reply|sound|talk)\b/i
];
function isExplicitSelfModificationRequest(text) {
  if (typeof text !== "string") {
    return false;
  }
  const normalized = text.trim();
  if (normalized.length === 0) {
    return false;
  }
  return EXPLICIT_SELF_MODIFICATION_PATTERNS.some((pattern) => pattern.test(normalized));
}

// src/services/embedding.ts
init_model();
init_service();

class EmbeddingGenerationService extends Service {
  static serviceType = "embedding-generation";
  capabilityDescription = "Handles asynchronous embedding generation for memories";
  queue = [];
  isProcessing = false;
  drainTaskId = null;
  maxQueueSize = 1000;
  batchSize = 10;
  processingIntervalMs = 100;
  isDisabled = false;
  static EMBEDDING_DRAIN_TASK = "EMBEDDING_DRAIN";
  static async start(runtime2) {
    runtime2.logger.info({
      src: "plugin:basic-capabilities:service:embedding",
      agentId: runtime2.agentId
    }, "Starting embedding generation service");
    const embeddingModel = runtime2.getModel(ModelType.TEXT_EMBEDDING);
    if (!embeddingModel) {
      runtime2.logger.warn({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: runtime2.agentId
      }, "No TEXT_EMBEDDING model registered - service will not be initialized");
      const noOpService = new EmbeddingGenerationService(runtime2);
      noOpService.isDisabled = true;
      return noOpService;
    }
    const service3 = new EmbeddingGenerationService(runtime2);
    await service3.initialize();
    return service3;
  }
  async initialize() {
    if (this.isDisabled) {
      this.runtime.logger.debug({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: this.runtime.agentId
      }, "Service is disabled, skipping initialization");
      return;
    }
    this.runtime.logger.info({
      src: "plugin:basic-capabilities:service:embedding",
      agentId: this.runtime.agentId
    }, "Initializing embedding generation service");
    this.runtime.registerEvent("EMBEDDING_GENERATION_REQUESTED" /* EMBEDDING_GENERATION_REQUESTED */, this.handleEmbeddingRequest.bind(this));
    this.registerDrainWorker();
    await this.ensureDrainTask();
  }
  registerDrainWorker() {
    this.runtime.registerTaskWorker({
      name: EmbeddingGenerationService.EMBEDDING_DRAIN_TASK,
      execute: async () => {
        if (!this.isProcessing && this.queue.length > 0) {
          await this.processQueue();
        }
        return;
      }
    });
  }
  async ensureDrainTask() {
    const rt = this.runtime;
    if (typeof rt.getTasksByName !== "function" || typeof rt.createTask !== "function") {
      return;
    }
    const agentId = rt.agentId;
    const existing = await rt.getTasksByName(EmbeddingGenerationService.EMBEDDING_DRAIN_TASK);
    const mine = existing.find((t) => t.agentId != null && String(t.agentId) === String(agentId));
    if (mine?.id) {
      this.drainTaskId = mine.id;
      return;
    }
    this.drainTaskId = await rt.createTask({
      name: EmbeddingGenerationService.EMBEDDING_DRAIN_TASK,
      tags: ["queue", "repeat"],
      worldId: agentId,
      metadata: {
        updateInterval: this.processingIntervalMs,
        baseInterval: this.processingIntervalMs,
        updatedAt: Date.now()
      }
    });
    this.runtime.logger.info({
      src: "plugin:basic-capabilities:service:embedding",
      agentId: this.runtime.agentId
    }, "Started embedding drain task");
  }
  async handleEmbeddingRequest(payload) {
    if (this.isDisabled) {
      this.runtime.logger.debug({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: this.runtime.agentId
      }, "Service is disabled, skipping embedding request");
      return;
    }
    const {
      memory: memory2,
      priority = "normal",
      retryCount = 0,
      maxRetries = 3,
      runId
    } = payload;
    if (memory2.embedding) {
      this.runtime.logger.debug({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: this.runtime.agentId,
        memoryId: memory2.id
      }, "Memory already has embeddings, skipping");
      return;
    }
    if (this.queue.length >= this.maxQueueSize) {
      this.runtime.logger.warn({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: this.runtime.agentId,
        queueSize: this.queue.length,
        maxSize: this.maxQueueSize
      }, "Queue is full, making room");
      this.makeRoomInQueue();
    }
    const queueItem = {
      memory: memory2,
      priority,
      retryCount,
      maxRetries,
      addedAt: Date.now(),
      runId
    };
    this.insertItemByPriority(queueItem);
    this.runtime.logger.debug({
      src: "plugin:basic-capabilities:service:embedding",
      agentId: this.runtime.agentId,
      queueSize: this.queue.length
    }, "Added memory to queue");
  }
  makeRoomInQueue() {
    const tenPercent = Math.floor(this.maxQueueSize * 0.1);
    const itemsToRemove = Math.min(10, Math.max(1, tenPercent));
    const itemsWithIndex = this.queue.map((item, index) => ({
      item,
      originalIndex: index
    }));
    itemsWithIndex.sort((a, b) => {
      const priorityOrder = { low: 0, normal: 1, high: 2 };
      const priorityDiff = priorityOrder[a.item.priority] - priorityOrder[b.item.priority];
      if (priorityDiff !== 0) {
        return priorityDiff;
      }
      return a.item.addedAt - b.item.addedAt;
    });
    const indicesToRemove = new Set(itemsWithIndex.slice(0, Math.min(itemsToRemove, itemsWithIndex.length)).map(({ originalIndex }) => originalIndex));
    const newQueue = this.queue.filter((_, index) => !indicesToRemove.has(index));
    const removedCount = this.queue.length - newQueue.length;
    this.queue = newQueue;
    this.runtime.logger.info({
      src: "plugin:basic-capabilities:service:embedding",
      agentId: this.runtime.agentId,
      removedCount,
      newSize: this.queue.length
    }, "Removed items from queue");
  }
  insertItemByPriority(queueItem) {
    if (queueItem.priority === "low" || this.queue.length === 0) {
      this.queue.push(queueItem);
      return;
    }
    let insertIndex = this.queue.length;
    for (let i = 0;i < this.queue.length; i++) {
      const priority = this.queue[i].priority;
      if (queueItem.priority === "high") {
        if (priority !== "high") {
          insertIndex = i;
          break;
        }
      } else if (priority === "low") {
        insertIndex = i;
        break;
      }
    }
    this.queue.splice(insertIndex, 0, queueItem);
  }
  async processQueue() {
    if (this.isProcessing || this.queue.length === 0) {
      return;
    }
    this.isProcessing = true;
    try {
      const batch = this.queue.splice(0, Math.min(this.batchSize, this.queue.length));
      this.runtime.logger.debug({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: this.runtime.agentId,
        batchSize: batch.length,
        remaining: this.queue.length
      }, "Processing batch");
      const promises = batch.map(async (item) => {
        try {
          await this.generateEmbedding(item);
        } catch (error) {
          this.runtime.logger.error({
            src: "plugin:basic-capabilities:service:embedding",
            agentId: this.runtime.agentId,
            memoryId: item.memory.id,
            error: error instanceof Error ? error.message : String(error)
          }, "Error processing item");
          if (item.retryCount < item.maxRetries) {
            item.retryCount++;
            this.insertItemByPriority(item);
            this.runtime.logger.debug({
              src: "plugin:basic-capabilities:service:embedding",
              agentId: this.runtime.agentId,
              retryCount: item.retryCount,
              maxRetries: item.maxRetries
            }, "Re-queued item for retry");
          } else {
            await this.runtime.log({
              entityId: this.runtime.agentId,
              roomId: item.memory.roomId || this.runtime.agentId,
              type: "embedding_event",
              body: {
                runId: item.runId,
                memoryId: item.memory.id,
                status: "failed",
                error: error instanceof Error ? error.message : String(error),
                source: "embeddingService"
              }
            });
            await this.runtime.emitEvent("EMBEDDING_GENERATION_FAILED" /* EMBEDDING_GENERATION_FAILED */, {
              runtime: this.runtime,
              memory: item.memory,
              error: error instanceof Error ? error.message : String(error),
              source: "embeddingService"
            });
          }
        }
      });
      await Promise.all(promises);
    } finally {
      this.isProcessing = false;
    }
  }
  async generateEmbedding(item) {
    const { memory: memory2 } = item;
    const memoryContent = memory2.content;
    if (!memoryContent?.text) {
      this.runtime.logger.warn({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: this.runtime.agentId,
        memoryId: memory2.id
      }, "Memory has no text content");
      return;
    }
    try {
      const startTime = Date.now();
      const embedding = await this.runtime.useModel(ModelType.TEXT_EMBEDDING, {
        text: memory2.content.text ?? ""
      });
      const duration2 = Date.now() - startTime;
      this.runtime.logger.debug({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: this.runtime.agentId,
        memoryId: memory2.id,
        durationMs: duration2
      }, "Generated embedding");
      if (memory2.id) {
        await this.runtime.updateMemory({
          id: memory2.id,
          embedding
        });
        await this.runtime.log({
          entityId: this.runtime.agentId,
          roomId: memory2.roomId || this.runtime.agentId,
          type: "embedding_event",
          body: {
            runId: item.runId,
            memoryId: memory2.id,
            status: "completed",
            duration: duration2,
            source: "embeddingService"
          }
        });
        await this.runtime.emitEvent("EMBEDDING_GENERATION_COMPLETED" /* EMBEDDING_GENERATION_COMPLETED */, {
          runtime: this.runtime,
          memory: { ...memory2, embedding },
          source: "embeddingService"
        });
      }
    } catch (error) {
      this.runtime.logger.error({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: this.runtime.agentId,
        memoryId: memory2.id,
        error: error instanceof Error ? error.message : String(error)
      }, "Failed to generate embedding");
      throw error;
    }
  }
  async stop() {
    this.runtime.logger.info({
      src: "plugin:basic-capabilities:service:embedding",
      agentId: this.runtime.agentId
    }, "Stopping embedding generation service");
    if (this.isDisabled) {
      this.runtime.logger.debug({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: this.runtime.agentId
      }, "Service is disabled, nothing to stop");
      return;
    }
    if (this.drainTaskId && typeof this.runtime.deleteTask === "function") {
      await this.runtime.deleteTask(this.drainTaskId).catch(() => {});
      this.drainTaskId = null;
    }
    const highPriorityItems = this.queue.filter((item) => item.priority === "high");
    if (highPriorityItems.length > 0) {
      this.runtime.logger.info({
        src: "plugin:basic-capabilities:service:embedding",
        agentId: this.runtime.agentId,
        count: highPriorityItems.length
      }, "Processing high priority items before shutdown");
      for (const item of highPriorityItems) {
        try {
          await this.generateEmbedding(item);
        } catch (error) {
          this.runtime.logger.error({
            src: "plugin:basic-capabilities:service:embedding",
            agentId: this.runtime.agentId,
            error: error instanceof Error ? error.message : String(error)
          }, "Error during shutdown processing");
        }
      }
    }
    this.runtime.logger.info({
      src: "plugin:basic-capabilities:service:embedding",
      agentId: this.runtime.agentId,
      remainingItems: this.queue.length
    }, "Stopped");
  }
  getQueueSize() {
    return this.queue.length;
  }
  getQueueStats() {
    const stats = {
      high: 0,
      normal: 0,
      low: 0,
      total: this.queue.length
    };
    for (const item of this.queue) {
      stats[item.priority]++;
    }
    return stats;
  }
  clearQueue() {
    const size = this.queue.length;
    this.queue = [];
    this.runtime.logger.info({
      src: "plugin:basic-capabilities:service:embedding",
      agentId: this.runtime.agentId,
      clearedCount: size
    }, "Cleared queue");
  }
}

