init_deterministic();
init_utils5();
var spec8 = requireProviderSpec("ACTIONS");
var actionsProvider = {
  name: spec8.name,
  description: spec8.description,
  position: spec8.position ?? -1,
  get: async (runtime2, message2, state2) => {
    const activeContexts = getActiveRoutingContexts(parseContextRoutingMetadata(state2?.values?.[CONTEXT_ROUTING_STATE_KEY]));
    const actionPromises = runtime2.actions.map(async (action) => {
      if (!shouldIncludeByContext(resolveActionContexts(action), activeContexts)) {
        return null;
      }
      const result = await action.validate(runtime2, message2, state2);
      if (result) {
        return action;
      }
      return null;
    });
    const resolvedActions = await Promise.all(actionPromises);
    const actionsData = resolvedActions.filter(Boolean);
    const actionSeed = buildDeterministicSeed(runtime2.agentId, message2.roomId, "ACTIONS");
    const actionNames = `Possible response actions: ${formatActionNames(actionsData, actionSeed)}`;
    const actionsWithDescriptions = actionsData.length > 0 ? addHeader("# Available Actions", formatActions(actionsData, actionSeed)) : "";
    const values = {
      actionNames,
      actionsWithDescriptions
    };
    const text = [actionNames, actionsWithDescriptions].filter(Boolean).join(`

`);
    return {
      data: {
        actionsData
      },
      values,
      text
    };
  }
};
// src/basic-capabilities/providers/attachments.ts
init_spec_helpers();
init_utils5();
var spec9 = requireProviderSpec("ATTACHMENTS");
var MAX_VISIBLE_ATTACHMENTS = 3;
function mergeConversationAttachments(message2, recentMessages) {
  const attachmentsById = new Map;
  const rememberAttachment = (attachment, createdAt) => {
    const existing = attachmentsById.get(attachment.id);
    if (existing && (existing._createdAt ?? 0) >= createdAt) {
      return;
    }
    attachmentsById.set(attachment.id, {
      ...attachment,
      _createdAt: createdAt
    });
  };
  for (const attachment of message2.content.attachments ?? []) {
    rememberAttachment(attachment, message2.createdAt ?? Date.now());
  }
  for (const recentMessage of recentMessages ?? []) {
    for (const attachment of recentMessage.content.attachments ?? []) {
      rememberAttachment(attachment, recentMessage.createdAt ?? Date.now());
    }
  }
  return Array.from(attachmentsById.values()).sort((left, right) => (right._createdAt ?? 0) - (left._createdAt ?? 0));
}
var attachmentsProvider = {
  name: spec9.name,
  description: spec9.description,
  dynamic: spec9.dynamic ?? true,
  get: async (runtime2, message2) => {
    const { roomId } = message2;
    const conversationLength = runtime2.getConversationLength();
    const recentMessagesData = await runtime2.getMemories({
      roomId,
      count: conversationLength,
      unique: false,
      tableName: "messages"
    });
    const allAttachments = mergeConversationAttachments(message2, Array.isArray(recentMessagesData) ? recentMessagesData : []);
    const visibleAttachments = allAttachments.slice(0, MAX_VISIBLE_ATTACHMENTS);
    const omittedCount = Math.max(0, allAttachments.length - visibleAttachments.length);
    const formattedAttachments = visibleAttachments.map((attachment) => `ID: ${attachment.id}
    Name: ${attachment.title}
    URL: ${attachment.url}
    Type: ${attachment.source}
    Content Type: ${attachment.contentType ?? "unknown"}
    Stored Content: ${attachment.text || attachment.description ? "available via READ_ATTACHMENT" : "none"}
    `).join(`
`);
    const omissionNotice = omittedCount > 0 ? `Showing the ${visibleAttachments.length} most recent attachments. ${omittedCount} older attachment${omittedCount === 1 ? "" : "s"} omitted from context; use READ_ATTACHMENT to inspect one.` : "";
    const text = formattedAttachments && formattedAttachments.length > 0 ? addHeader("# Attachments", [formattedAttachments, omissionNotice].filter(Boolean).join(`

`)) : "";
    const values = {
      attachments: text
    };
    const data2 = {
      attachments: allAttachments,
      visibleAttachments,
      omittedCount
    };
    return {
      values,
      data: data2,
      text
    };
  }
};
