    const worldRooms = await runtime2.getRooms(worldId);
    logger.debug({
      src: "plugin:basic-capabilities:provider:world",
      agentId: runtime2.agentId,
      roomCount: worldRooms.length,
      worldName: world.name
    }, "Found rooms in world");
