init_utils5();
var spec21 = requireActionSpec("FOLLOW_ROOM");
var FOLLOW_KEYWORDS = [
  "follow",
  "participate",
  "engage",
  "listen",
  "take interest",
  "join"
];
var followRoomAction = {
  name: spec21.name,
  similes: spec21.similes ? [...spec21.similes] : [],
  description: spec21.description,
  examples: spec21.examples ?? [],
  validate: async (runtime2, message2) => {
    const messageContentText = message2.content.text?.toLowerCase();
    if (!messageContentText || !FOLLOW_KEYWORDS.some((keyword) => messageContentText.includes(keyword))) {
      return false;
    }
    const roomId = message2.roomId;
    const roomState = await runtime2.getParticipantUserState(roomId, runtime2.agentId);
    return roomState !== "FOLLOWED" && roomState !== "MUTED";
  },
  handler: async (runtime2, message2, state2, _options, _callback, _responses) => {
    if (!state2) {
      logger.error({
        src: "plugin:advanced-capabilities:action:follow_room",
        agentId: runtime2.agentId
      }, "State is required for followRoomAction");
      return {
        text: "State is required for follow room action",
        values: {
          success: false,
          error: "STATE_REQUIRED"
        },
        data: {
          actionName: "FOLLOW_ROOM",
          error: "State is required"
        },
        success: false,
        error: new Error("State is required for followRoomAction")
      };
    }
    async function _shouldFollow(state3) {
      const shouldFollowPrompt = composePromptFromState({
        state: state3,
        template: shouldFollowRoomTemplate
      });
      const response = await runtime2.useModel(ModelType.TEXT_SMALL, {
        prompt: shouldFollowPrompt,
        stopSequences: []
      });
      const parsed = parseKeyValueXml(response);
      const decisionValue = parsed?.decision ?? response.trim();
      const cleanedResponse = String(decisionValue).trim().toLowerCase();
      if (parseBooleanFromText2(decisionValue) || cleanedResponse.includes("true") || cleanedResponse.includes("yes")) {
        await runtime2.createMemory({
          entityId: message2.entityId,
          agentId: message2.agentId,
          roomId: message2.roomId,
          content: {
            source: message2.content.source,
            thought: "I will now follow this room and chime in",
            actions: ["FOLLOW_ROOM_STARTED"]
          }
        }, "messages");
        return true;
      }
      if (cleanedResponse === "false" || cleanedResponse === "no" || cleanedResponse === "n" || cleanedResponse.includes("false") || cleanedResponse.includes("no")) {
        await runtime2.createMemory({
          entityId: message2.entityId,
          agentId: message2.agentId,
          roomId: message2.roomId,
          content: {
            source: message2.content.source,
            thought: "I decided to not follow this room",
            actions: ["FOLLOW_ROOM_FAILED"]
          }
        }, "messages");
        return false;
      }
      logger.warn({
        src: "plugin:advanced-capabilities:action:follow_room",
        agentId: runtime2.agentId,
        response
      }, "Unclear boolean response, defaulting to false");
      return false;
    }
    const shouldFollow = await _shouldFollow(state2);
    const room = state2.data.room ?? await runtime2.getRoom(message2.roomId);
    if (!room) {
      return {
        text: "Could not find room to follow",
        values: { success: false, error: "ROOM_NOT_FOUND" },
        data: { actionName: "FOLLOW_ROOM", error: "Room not found" },
        success: false
      };
    }
    const roomName = room.name ?? `Room-${message2.roomId.substring(0, 8)}`;
    if (shouldFollow) {
      try {
        await runtime2.updateParticipantUserState(message2.roomId, runtime2.agentId, "FOLLOWED");
        await runtime2.createMemory({
          entityId: message2.entityId,
          agentId: message2.agentId,
          roomId: message2.roomId,
          content: {
            thought: `I followed the room ${roomName}`,
            actions: ["FOLLOW_ROOM_START"]
          }
        }, "messages");
        return {
          text: `Now following room: ${roomName}`,
          values: {
            success: true,
            roomFollowed: true,
            roomId: message2.roomId,
            roomName,
            newState: "FOLLOWED"
          },
          data: {
            actionName: "FOLLOW_ROOM",
            roomId: message2.roomId,
            roomName,
            followed: true
          },
          success: true
        };
      } catch (error) {
        logger.error({
          src: "plugin:advanced-capabilities:action:follow_room",
          agentId: runtime2.agentId,
          error: error instanceof Error ? error.message : String(error)
        }, "Error following room");
        return {
          text: "Failed to follow room",
          values: {
            success: false,
            error: "FOLLOW_FAILED"
          },
          data: {
            actionName: "FOLLOW_ROOM",
            error: error instanceof Error ? error.message : String(error),
            roomId: message2.roomId
          },
          success: false,
          error: error instanceof Error ? error : new Error(String(error))
        };
      }
    } else {
      return {
        text: `Decided not to follow room: ${roomName}`,
        values: {
          success: true,
          roomFollowed: false,
          roomId: message2.roomId,
          roomName,
          reason: "NOT_APPROPRIATE"
        },
        data: {
          actionName: "FOLLOW_ROOM",
          roomId: message2.roomId,
          roomName,
          followed: false,
          reason: "Decision criteria not met"
        },
        success: true
      };
    }
  }
};
// src/advanced-capabilities/actions/imageGeneration.ts
