var spec22 = requireActionSpec("GENERATE_IMAGE");
var IMAGE_EXTENSIONS = new Set(["png", "jpg", "jpeg", "gif", "webp", "bmp"]);
var getFileExtension = (url) => {
  const urlPath = new URL(url).pathname;
  const lastDot = urlPath.lastIndexOf(".");
  if (lastDot === -1 || lastDot === urlPath.length - 1) {
    return "png";
  }
  const extension2 = urlPath.slice(lastDot + 1).toLowerCase();
  return IMAGE_EXTENSIONS.has(extension2) ? extension2 : "png";
};
var generateImageAction = {
  name: spec22.name,
  similes: spec22.similes ? [...spec22.similes] : [],
  description: spec22.description,
  validate: async (_runtime) => {
    return true;
  },
  handler: async (runtime2, message2, state2, _options, callback, responses) => {
    const allProviders = [];
    if (responses) {
      for (const res of responses) {
        const providers = res.content?.providers;
        if (providers && providers.length > 0) {
          allProviders.push(...providers);
        }
      }
    }
    state2 = await runtime2.composeState(message2, [
      ...allProviders ?? [],
      "RECENT_MESSAGES"
    ]);
    const prompt = composePromptFromState({
      state: state2,
      template: runtime2.character.templates?.imageGenerationTemplate || imageGenerationTemplate
    });
    const promptResponse = await runtime2.useModel(ModelType.TEXT_LARGE, {
      prompt,
      stopSequences: []
    });
    const parsedXml = parseKeyValueXml(promptResponse);
    const promptValue = parsedXml?.prompt;
    const imagePrompt = typeof promptValue === "string" ? promptValue : "Unable to generate descriptive prompt for image";
    const imageResponse = await runtime2.useModel(ModelType.IMAGE, {
      prompt: imagePrompt
    });
    const imageResults = Array.isArray(imageResponse) ? imageResponse : typeof imageResponse === "string" ? [imageResponse] : [];
    const firstImage = imageResults[0];
    const firstImageUrl = typeof firstImage === "string" ? firstImage : firstImage?.url;
    if (imageResults.length === 0 || !firstImageUrl) {
      logger.error({
        src: "plugin:advanced-capabilities:action:image_generation",
        agentId: runtime2.agentId,
        imagePrompt
      }, "Image generation failed - no valid response received");
      return {
        text: "Image generation failed",
        values: {
          success: false,
          error: "IMAGE_GENERATION_FAILED",
          prompt: imagePrompt
        },
        data: {
          actionName: "GENERATE_IMAGE",
          prompt: imagePrompt,
          rawResponse: imageResults.map((image) => ({
            url: typeof image === "string" ? image : image.url
          }))
        },
        success: false
      };
    }
    const imageUrl = firstImageUrl;
    logger.info({
      src: "plugin:advanced-capabilities:action:image_generation",
      agentId: runtime2.agentId,
      imageUrl
    }, "Received image URL");
    const extension2 = getFileExtension(imageUrl);
    const timestamp2 = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
    const fileName = `Generated_Image_${timestamp2}.${extension2}`;
    const attachmentId = v4_default2();
    const responseContent = {
      attachments: [
        {
          id: attachmentId,
          url: imageUrl,
          title: fileName,
          contentType: ContentType.IMAGE
        }
      ],
      thought: `Generated an image based on: "${imagePrompt}"`,
      actions: ["GENERATE_IMAGE"],
      text: imagePrompt
    };
    if (callback) {
      await callback(responseContent);
    }
    return {
      text: "Generated image",
      values: {
        success: true,
        imageGenerated: true,
        imageUrl,
        prompt: imagePrompt
      },
      data: {
        actionName: "GENERATE_IMAGE",
        imageUrl,
        prompt: imagePrompt
      },
      success: true
    };
  },
  examples: spec22.examples ?? []
};
