var contactsProvider = {
  name: spec37.name,
  description: spec37.description,
  get: async (runtime2, _message, _state2) => {
    const relationshipsService = runtime2.getService("relationships");
    if (!relationshipsService) {
      runtime2.logger.warn("[ContactsProvider] RelationshipsService not available");
      return { text: "", values: {}, data: {} };
    }
    const contacts = await relationshipsService.searchContacts({});
    if (contacts.length === 0) {
      return {
        text: "No contacts in relationships.",
        values: { contactCount: 0 },
        data: {}
      };
    }
    const contactDetails = await Promise.all(contacts.map(async (contact) => {
      const entity = await runtime2.getEntityById(contact.entityId);
      const displayName = typeof contact.customFields.displayName === "string" ? contact.customFields.displayName : null;
      return {
        id: contact.entityId,
        name: entity?.names[0] || displayName || "Unknown",
        categories: contact.categories,
        tags: contact.tags,
        preferences: contact.preferences,
        lastModified: contact.lastModified
      };
    }));
    const grouped = {};
    for (const contact of contactDetails) {
      for (const cat of contact.categories) {
        const bucket = grouped[cat];
        if (bucket) {
          bucket.push(contact);
        } else {
          grouped[cat] = [contact];
        }
      }
    }
    const lines = [];
    lines.push(`You have ${contacts.length} contacts in your relationships:`);
    const categoryCounts = {};
    for (const category in grouped) {
      const items = grouped[category];
      if (!items)
        continue;
      categoryCounts[category] = items.length;
      lines.push("", `${category.charAt(0).toUpperCase() + category.slice(1)}s (${items.length}):`);
      for (const item of items) {
        let line = `- ${item.name}`;
        if (item.tags.length > 0) {
          line += ` [${item.tags.join(", ")}]`;
        }
        lines.push(line);
      }
    }
    const textSummary = lines.join(`
`).trim();
    return {
      text: textSummary,
      values: {
        contactCount: contacts.length,
        ...categoryCounts
      },
      data: categoryCounts
    };
  }
};
