class Semaphore {
  permits;
  queue = [];
  constructor(count) {
    this.permits = Math.max(1, count);
  }
  async acquire() {
    if (this.permits > 0) {
      this.permits -= 1;
      return;
    }
    await new Promise((resolve) => {
      this.queue.push(resolve);
    });
  }
  release() {
    this.permits += 1;
    const next = this.queue.shift();
    if (next && this.permits > 0) {
      this.permits -= 1;
      next();
    }
  }
}

