// src/features/trajectories/index.ts
var pendingTrajectoryStepByReplyId = new Map;
var pendingTrajectoryStepByMessageId = new Map;
var pendingTrajectoryMessageIdByStepId = new Map;
var pendingTrajectoryEndTargetByStepId = new Map;
function cleanupPendingTrajectory(runtime2, trajectoryStepId) {
  const sourceMessageId = pendingTrajectoryMessageIdByStepId.get(trajectoryStepId);
  if (sourceMessageId) {
    pendingTrajectoryStepByMessageId.delete(sourceMessageId);
    pendingTrajectoryStepByReplyId.delete(createUniqueUuid(runtime2, sourceMessageId));
    pendingTrajectoryMessageIdByStepId.delete(trajectoryStepId);
  }
  pendingTrajectoryEndTargetByStepId.delete(trajectoryStepId);
}
async function endPendingTrajectory(runtime2, trajectoryStepId, status) {
  const logger3 = TrajectoriesService.resolveFromRuntime(runtime2);
  if (!logger3) {
    cleanupPendingTrajectory(runtime2, trajectoryStepId);
    return;
  }
  try {
    const endTarget = pendingTrajectoryEndTargetByStepId.get(trajectoryStepId) ?? trajectoryStepId;
    await logger3.endTrajectory(endTarget, status);
  } finally {
    cleanupPendingTrajectory(runtime2, trajectoryStepId);
  }
}
function getFinalStatusForRun(payload) {
  if (payload.status === "timeout") {
    return "timeout";
  }
  return payload.status === "completed" ? "completed" : "terminated";
}
function buildTrajectoryMetadata(message2, meta) {
  const metadata = {
    roomId: message2.roomId,
    entityId: message2.entityId
  };
  if (typeof message2.id === "string" && message2.id.length > 0) {
    metadata.messageId = message2.id;
  }
  const channelType = typeof meta.channelType === "string" && meta.channelType.length > 0 ? meta.channelType : typeof message2.content?.channelType === "string" && message2.content.channelType.length > 0 ? message2.content.channelType : null;
  if (channelType) {
    metadata.channelType = channelType;
  }
  if (typeof meta.sessionKey === "string" && meta.sessionKey.length > 0) {
    metadata.conversationId = meta.sessionKey;
  }
  return metadata;
}
var trajectoriesPlugin = {
  name: "trajectories",
  description: "Captures and persists complete agent interaction trajectories for debugging, analysis, and RL training. " + "Records LLM calls, provider accesses, actions, environment state, and computes rewards.",
  dependencies: ["@elizaos/plugin-sql"],
  services: [TrajectoriesService],
  events: {
    MESSAGE_RECEIVED: [
      async (payload) => {
        const { runtime: runtime2, message: message2, source } = payload;
        if (!message2 || !runtime2)
          return;
        if (!message2.metadata) {
          message2.metadata = {
            type: "message"
          };
        }
        const meta = message2.metadata;
        const logger3 = TrajectoriesService.resolveFromRuntime(runtime2);
        if (!logger3)
          return;
        let trajectoryStepId = crypto2.randomUUID();
        meta.trajectoryStepId = trajectoryStepId;
        try {
          const trajectoryId = await logger3.startTrajectory(runtime2.agentId, {
            source: source ?? meta.source ?? "chat",
            metadata: buildTrajectoryMetadata(message2, meta)
          });
          const normalizedTrajectoryId = typeof trajectoryId === "string" && trajectoryId.trim().length > 0 ? trajectoryId : null;
          if (normalizedTrajectoryId) {
            const runtimeStepId = logger3.startStep(normalizedTrajectoryId, {
              timestamp: Date.now(),
              agentBalance: 0,
              agentPoints: 0,
              agentPnL: 0,
              openPositions: 0
            });
            const normalizedStepId = typeof runtimeStepId === "string" && runtimeStepId.trim().length > 0 ? runtimeStepId : trajectoryStepId;
            trajectoryStepId = normalizedStepId;
            meta.trajectoryStepId = trajectoryStepId;
            pendingTrajectoryEndTargetByStepId.set(trajectoryStepId, normalizedTrajectoryId);
            if (typeof logger3.flushWriteQueue === "function") {
              await logger3.flushWriteQueue(normalizedTrajectoryId);
            }
          } else {}
          if (message2.id) {
            const replyId = createUniqueUuid(runtime2, message2.id);
            pendingTrajectoryStepByReplyId.set(replyId, trajectoryStepId);
            pendingTrajectoryStepByMessageId.set(message2.id, trajectoryStepId);
            pendingTrajectoryMessageIdByStepId.set(trajectoryStepId, message2.id);
          }
        } catch (err) {
          runtime2.logger?.warn({
            err,
            src: "trajectories",
            roomId: message2.roomId
          }, "Failed to start trajectory logging");
        }
      }
    ],
    MESSAGE_SENT: [
      async (payload) => {
        const { runtime: runtime2, message: message2 } = payload;
        if (!message2 || !runtime2)
          return;
        const meta = message2.metadata;
        const inReplyTo = typeof message2.content === "object" && message2.content !== null && "inReplyTo" in message2.content && typeof message2.content.inReplyTo === "string" ? message2.content.inReplyTo : undefined;
        let trajectoryStepId = meta?.trajectoryStepId;
        if (!trajectoryStepId && inReplyTo) {
          trajectoryStepId = pendingTrajectoryStepByReplyId.get(inReplyTo);
        }
        if (!trajectoryStepId)
          return;
        try {
          await endPendingTrajectory(runtime2, trajectoryStepId, "completed");
        } catch (err) {
          runtime2.logger?.warn({
            err,
            src: "trajectories",
            trajectoryStepId
          }, "Failed to end trajectory logging");
        }
      }
    ],
    RUN_ENDED: [
      async (payload) => {
        const { runtime: runtime2, messageId } = payload;
        if (!runtime2 || !messageId)
          return;
        const trajectoryStepId = pendingTrajectoryStepByMessageId.get(messageId);
        if (!trajectoryStepId)
          return;
        try {
          await endPendingTrajectory(runtime2, trajectoryStepId, getFinalStatusForRun(payload));
        } catch (err) {
          runtime2.logger?.warn({
            err,
            src: "trajectories",
            messageId,
            trajectoryStepId
          }, "Failed to end trajectory logging on run completion");
        }
      }
    ],
    RUN_TIMEOUT: [
      async (payload) => {
        const { runtime: runtime2, messageId } = payload;
        if (!runtime2 || !messageId)
          return;
        const trajectoryStepId = pendingTrajectoryStepByMessageId.get(messageId);
        if (!trajectoryStepId)
          return;
        try {
          await endPendingTrajectory(runtime2, trajectoryStepId, "timeout");
        } catch (err) {
          runtime2.logger?.warn({
            err,
            src: "trajectories",
            messageId,
            trajectoryStepId
          }, "Failed to end trajectory logging on run timeout");
        }
      }
    ]
  }
};

