function createOnboardingStateMachine(config2) {
  return new OnboardingStateMachine({
    mode: "conversational",
    ...config2
  });
}
function isOnboardingComplete(context) {
  return context.currentStep === OnboardingStep.COMPLETE;
}
function getOnboardingSummary(context) {
  const progress = calculateProgress(context);
  const stepLabel = ONBOARDING_STEP_LABELS[context.currentStep];
  const stepDescription = ONBOARDING_STEP_DESCRIPTIONS[context.currentStep];
  let summary = `## Onboarding Progress: ${progress}%

`;
  summary += `**Current Step:** ${stepLabel}
`;
  summary += `**Description:** ${stepDescription}

`;
  if (context.completedSteps.length > 0) {
    summary += `**Completed Steps:**
`;
    for (const step of context.completedSteps) {
      summary += `- ${ONBOARDING_STEP_LABELS[step]}
`;
    }
    summary += `
`;
  }
  if (context.errors.length > 0) {
    summary += `**Errors:**
`;
    for (const error of context.errors) {
      summary += `- [${error.step}] ${error.message}
`;
    }
  }
  return summary;
}

